INSERT INTO found_bug
(id,title,severity,category,ddl_op,feature,symptom,repro,expected,actual,root_cause,fix_hint,oracle,method,root_cause_id,affects,confirmed,status,issue_url,notes)
VALUES
(1830003,'Cancelled SET TIFLASH REPLICA 0 removes the active PD rule and causes TiFlash-only query timeout','high','ddl_control_plane','ALTER TABLE ... SET TIFLASH REPLICA','TiFlash placement rules','Cancelled DDL leaves metadata at REPLICA_COUNT=1 and AVAILABLE=1 while the required PD rule is absent; TiFlash-only queries time out.','Start from a synchronized TiFlash replica, pause after ConfigureTiFlashPDForTable deletes the rule for count 0, ADMIN CANCEL the DDL, release it, then compare history, INFORMATION_SCHEMA.TIFLASH_REPLICA, PD rules, and a TiFlash-only query.','Cancellation retains the count=1 PD rule required by committed available metadata.','ALTER returns 8214 and history is cancelled; metadata remains count=1/available=1, PD rule is absent, and tidb_isolation_read_engines=tiflash query returns 9012 timeout.','onSetTableFlashReplica mutates the PD rule before local metadata/job publication and generic cancellation has no compensation.','Use a durable intent/reconciler or restore the rule derived from committed metadata on every post-PD abort edge.','ddl-tiflash-metadata-pd-query-coherence','source-proof-local-real-tiflash-matrix','tiflash-rule-delete-before-ddl-commit','master 13282a8bd06b',1,'issue-filed','https://github.com/pingcap/tidb/issues/69785','Independent mock-TiFlash and real PD/TiKV/TiFlash RED; normal removal and committed-rule compensation controls GREEN; PR/review/history excluded from discovery; exact-root issue dedup only after RED.');
